css:
.clippy-container {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 8px;
  width: 290px;
  font-family: Tahoma, "MS Sans Serif", Geneva, sans-serif;
  user-select: none;
}

.clippy-bubble {
  position: relative;
  background-color: #ffffe1;
  border: 1px solid #000000;
  box-shadow: 3px 3px 0px #000000;
  padding: 6px 8px 10px 10px;
  width: 100%;
  box-sizing: border-box;
}

.clippy-titlebar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px dotted #808080;
  padding-bottom: 3px;
  margin-bottom: 8px;
}

.clippy-title-left {
  display: flex;
  align-items: center;
  gap: 4px;
}

.clippy-bulb {
  font-size: 11px;
}

.clippy-title-text {
  font-size: 11px;
  font-weight: bold;
  color: #000080;
  letter-spacing: -0.2px;
}

.clippy-close {
  background: transparent;
  border: none;
  font-family: monospace;
  font-size: 14px;
  font-weight: bold;
  color: #000000;
  cursor: pointer;
  padding: 0 2px;
  line-height: 1;
}

.clippy-close:hover {
  color: #ff0000;
}

.clippy-content {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.clippy-main-text {
  font-size: 11px;
  color: #000000;
  line-height: 1.35;
  margin: 0;
}

.clippy-prompt-text {
  font-size: 11px;
  font-weight: bold;
  color: #000000;
  margin: 0;
}

.clippy-options {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding-left: 2px;
}

.clippy-opt-btn {
  display: flex;
  align-items: flex-start;
  gap: 7px;
  background: transparent;
  border: none;
  text-align: left;
  padding: 2px 4px 2px 2px;
  cursor: pointer;
  width: 100%;
  border-radius: 0;
}

.clippy-bullet {
  flex-shrink: 0;
  margin-top: 4px;
  width: 5px;
  height: 5px;
  background-color: #0000ff;
  border-radius: 50%;
  box-shadow: inset -1px -1px 0px rgba(0, 0, 0, 0.5);
}

.clippy-opt-text {
  font-family: inherit;
  font-size: 11px;
  color: #0000ff;
  text-decoration: none;
  line-height: 1.25;
}

.clippy-opt-btn:hover {
  background-color: #000080;
}

.clippy-opt-btn:hover .clippy-opt-text {
  color: #ffffff;
  text-decoration: underline;
}

.clippy-opt-btn:hover .clippy-bullet {
  background-color: #ffffff;
}

.clippy-tail {
  position: absolute;
  bottom: -9px;
  right: 40px;
  width: 0;
  height: 0;
  border-left: 6px solid transparent;
  border-right: 6px solid transparent;
  border-top: 9px solid #ffffe1;
}

.clippy-tail::after {
  content: "";
  position: absolute;
  bottom: 1px;
  right: -7px;
  width: 0;
  height: 0;
  border-left: 7px solid transparent;
  border-right: 7px solid transparent;
  border-top: 10px solid #000000;
  z-index: -1;
}

.clippy-sprite-wrapper {
  margin-right: 15px;
  z-index: 10;
}

.clippy-sprite {
  width: 85px;
  height: 105px;
  cursor: pointer;
  animation: clippy-idle 4s ease-in-out infinite alternate;
}

.clippy-svg {
  width: 100%;
  height: 100%;
}

.clippy-eye {
  transform-origin: 50% 43px;
  animation: clippy-blink 5s infinite ease-in-out;
}

.clippy-sprite:hover {
  animation: clippy-bounce 0.5s ease-in-out infinite alternate;
}

.clippy-sprite:hover .clippy-brow {
  transform: translateY(-3px);
  transition: transform 0.1s ease-out;
}

.clippy-brow {
  transition: transform 0.3s ease-in;
}

@keyframes clippy-idle {
  0% {
    transform: translateY(0) scaleY(1);
  }
  50% {
    transform: translateY(-2px) scaleY(0.99);
  }
  100% {
    transform: translateY(1px) scaleY(1);
  }
}

@keyframes clippy-blink {
  0%,
  92%,
  98%,
  100% {
    transform: scaleY(1);
  }
  94%,
  96% {
    transform: scaleY(0.08);
  }
}

@keyframes clippy-bounce {
  0% {
    transform: translateY(0) rotate(-2deg);
  }
  100% {
    transform: translateY(-4px) rotate(2deg);
  }
}
